                try { $mine = ([string](Get-PropertyValue (ConvertFrom-Json -InputObject $text) 'token' '')) -ceq $Token } catch { $mine = $false }
            } finally { $fs.Dispose() }
            if ($mine) { [IO.File]::Delete($Path) }
            return
        } catch { Start-Sleep -Milliseconds 50 }
    }
}

